// Assembles index.html and assets/js/i18n.js from the sources in sections/.
//   node tools/build.js           writes both files
//   node tools/build.js --check   only reports whether they are up to date (exit code 1 if not)
//   node tools/build.js --force   also overwrites a generated file that was edited by hand
//
// sections/layout.html is the page frame: head, top bar and footer. In the output, each
// line of the form <!-- Title: sections/<name>/content.html --> is followed by that file,
// indented to the marker. The English and Spanish text of the frame (layout.text.js) and
// of each section (<name>/text.js) is merged, in the order of the markers, into the
// translations object of assets/js/i18n.js.
//
// The first comment of each generated file carries a stamp: a hash of the rest of the file.
// A file whose content no longer matches its stamp was edited by hand, and the build does
// not overwrite it unless --force is given, so that those edits can first be moved into
// sections/.
const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

const ROOT = path.join(__dirname, '..');
const HTML_OUTPUT = 'index.html';
const I18N_OUTPUT = 'assets/js/i18n.js';
const MARKER = /^( *)<!-- [^:]+: sections\/([a-z-]+)\/content\.html -->$/;
const STAMP = '{stamp}';
const HTML_NOTICE = `<!-- Generated by tools/build.js from sections/: edit the files there, not this one (build ${STAMP}). -->`;
const I18N_NOTICE = `// Generated by tools/build.js from sections/layout.text.js and sections/*/text.js: edit those files, not this one (build ${STAMP}).`;
const STAMP_PATTERN = /\(build ([0-9a-f]{12})\)/;

const read = (file) => fs.readFileSync(path.join(ROOT, file), 'utf8').replace(/\r\n/g, '\n');
const digest = (text) => crypto.createHash('sha256').update(text).digest('hex').slice(0, 12);
const stamp = (text) => text.replace(STAMP, digest(text));

// True when the file content does not match the stamp written by the build.
function editedByHand(text) {
    const match = text.match(STAMP_PATTERN);
    return !match || digest(text.replace(match[0], `(build ${STAMP})`)) !== match[1];
}

function trimBlankLines(lines) {
    const out = lines.slice();
    while (out.length && !out[0].trim()) out.shift();
    while (out.length && !out[out.length - 1].trim()) out.pop();
    return out;
}

function buildHtml() {
    const sections = [];
    const out = [];
    for (const line of read('sections/layout.html').split('\n')) {
        out.push(line);
        if (/^<html[\s>]/.test(line)) out.push(HTML_NOTICE);
        const match = line.match(MARKER);
        if (!match) continue;
        const [, pad, name] = match;
        if (sections.includes(name)) throw new Error(`sections/layout.html: section ${name} is included twice`);
        sections.push(name);
        const content = trimBlankLines(read(`sections/${name}/content.html`).split('\n'));
        out.push(...content.map((contentLine) => (contentLine ? pad + contentLine : contentLine)));
    }
    if (!sections.length) throw new Error('sections/layout.html: no section markers found');
    return { html: stamp(out.join('\n')), sections };
}

// A text file is an object literal ({ en: { ... }, es: { ... } }). Its two bodies are copied
// line by line, so that comments and formatting are kept in the generated file.
function readText(file) {
    const source = read(file);
    let value;
    try {
        value = Function(`return (\n${source}\n);`)();
    } catch (error) {
        throw new Error(`${file}: ${error.message}`);
    }
    const lines = source.split('\n');
    const body = (open, close) => {
        const start = lines.indexOf(open);
        const end = lines.indexOf(close, start + 1);
        if (start < 0 || end < 0) throw new Error(`${file}: expected the lines "${open}" and "${close}"`);
        return trimBlankLines(lines.slice(start + 1, end));
    };
    const missingEs = Object.keys(value.en || {}).filter((key) => !(key in (value.es || {})));
    const missingEn = Object.keys(value.es || {}).filter((key) => !(key in (value.en || {})));
    if (missingEs.length || missingEn.length) {
        throw new Error(`${file}: keys without Spanish text: ${missingEs.join(', ') || 'none'}; keys without English text: ${missingEn.join(', ') || 'none'}`);
    }
    return { file, value, en: body('    en: {', '    },'), es: body('    es: {', '    }') };
}

function buildI18n(sections) {
    const texts = ['sections/layout.text.js', ...sections.map((name) => `sections/${name}/text.js`)].map(readText);
    const owner = new Map();
    for (const { file, value } of texts) {
        for (const key of Object.keys(value.en)) {
            if (owner.has(key)) throw new Error(`${file}: key ${key} is already defined in ${owner.get(key)}`);
            owner.set(key, file);
        }
    }
    const out = [I18N_NOTICE, 'const translations = {'];
    for (const language of ['en', 'es']) {
        out.push(`    ${language}: {`);
        texts.forEach((text, index) => {
            const body = text[language].slice();
            const last = body.length - 1;
            if (index < texts.length - 1 && last >= 0 && !body[last].trimEnd().endsWith(',')) body[last] += ',';
            if (index && body.length) out.push('');
            out.push(...body);
        });
        out.push(language === 'en' ? '    },' : '    }');
    }
    out.push('};', '');
    const i18n = stamp(out.join('\n'));

    // The generated object has to hold exactly the text of the sources.
    const generated = Function(`${i18n}\nreturn translations;`)();
    for (const language of ['en', 'es']) {
        const expected = Object.assign({}, ...texts.map((text) => text.value[language]));
        if (JSON.stringify(generated[language]) !== JSON.stringify(expected)) {
            throw new Error(`${I18N_OUTPUT}: the generated ${language} text differs from the sources`);
        }
    }
    return i18n;
}

function build() {
    const { html, sections } = buildHtml();
    return { [HTML_OUTPUT]: html, [I18N_OUTPUT]: buildI18n(sections) };
}

// Generated files whose content on disk differs from the sources (line endings ignored),
// split into those left as the build wrote them and those edited by hand since.
function status(outputs = build()) {
    const stale = Object.entries(outputs)
        .filter(([file, text]) => !fs.existsSync(path.join(ROOT, file)) || read(file) !== text)
        .map(([file]) => file);
    const edited = stale.filter((file) => fs.existsSync(path.join(ROOT, file)) && editedByHand(read(file)));
    return { stale, edited };
}

function describe({ stale, edited }) {
    const messages = [];
    if (edited.length) {
        messages.push(`${edited.join(', ')} edited by hand: move those edits into sections/, then run node tools/build.js ` +
            '(node tools/build.js --force discards them).');
    }
    const outdated = stale.filter((file) => !edited.includes(file));
    if (outdated.length) messages.push(`${outdated.join(', ')} out of date: run node tools/build.js.`);
    return messages.join(' ');
}

module.exports = { build, status, describe };

if (require.main === module) {
    const outputs = build();
    const state = status(outputs);
    const force = process.argv.includes('--force');
    if (process.argv.includes('--check') || (state.edited.length && !force)) {
        if (state.stale.length) {
            console.error(describe(state));
            process.exit(1);
        }
        console.log(`${Object.keys(outputs).join(' and ')} are up to date`);
    } else {
        for (const file of state.stale) fs.writeFileSync(path.join(ROOT, file), outputs[file]);
        console.log(state.stale.length ? `Written: ${state.stale.join(', ')}` : 'Nothing to update');
    }
}
